import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEco6,validEco6,advanceEco6,numericEco6,experimentOptions,experimentResult,experimentCases,experimentValid}from './eco6-models.js?v=20261023-physicscomplete01';import{showEco6}from './eco6-visuals.js?v=20261023-physicscomplete01';export{showEco6};
export function mountEco6(l,p,root,{save,done,feedback}){let ts=tasksForEco6(l.widget.slice(5)),w=p.widget;w.eco6Task??=ts[0].id;w.eco6Drafts??={};w.eco6Passed??=[];let i=ts.findIndex(t=>t.id===w.eco6Task);if(i<0)i=0;let t=ts[i],v=w.eco6Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEco6(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.eco6Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('eco6Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('eco6Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEco6">Reveal evidence →</button><p id="eco6Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEco6(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#eco6Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEco6(c,v.answer);}
else if(t.type==='sequence'){body=field('eco6Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEco6">Advance pathway →</button><p id="eco6Readout" aria-live="polite"></p>';draw=()=>{showEco6(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#eco6Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('eco6A',o.labels[0],o.a,v.a)+field('eco6B',o.labels[1],o.b,v.b)+'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="eco6Prediction" value="'+(v.prediction??'')+'"></label><button class="secondary" id="eco6Run">Reveal model output →</button><p id="eco6Output"></p>'+field('eco6Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showEco6(t.kind,{a:v.a,b:v.b,revealed:v.ran,title:t.title});$('#eco6Output').textContent=v.ran?'Model output: '+r.value+' '+o.unit:'Predict first. Figures and settings are original teaching assumptions.';};valid=()=>!!v.ran&&numericEco6(v.prediction,experimentResult(t.experiment,v.a,v.b).value);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="eco6Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="eco6Number" type="number" step="any" value="'+(v.number??'')+'">'+field('eco6Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEco6(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEco6(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="eco6Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEco6">Record reasoning</button><button class="secondary" id="nextEco6">Next challenge →</button></div><p id="eco6Progress"></p>';
const status=()=>{$('#eco6Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.eco6Passed.includes(t.id)?'Challenge recorded.':'';$('#eco6Progress').textContent=ts.filter(t=>w.eco6Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='eco6A'||id==='eco6B'){if(!val)return;v[id==='eco6A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='eco6Interpretation'){v.interpretation=val;save();return;}if(id==='eco6Prediction'){v.prediction=val;save();return;}if(id==='eco6Case'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='eco6Answer')v.answer=val;else if(id==='eco6Next')v.next=val;else if(id==='eco6Number')v.number=val;else if(id==='eco6Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='eco6Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#eco6Run'))$('#eco6Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a number first.',true);return;}v.ran=true;save();draw();};
if($('#revealEco6'))$('#revealEco6').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEco6(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEco6(t.cases[v.case],v.answer));};
if($('#advanceEco6'))$('#advanceEco6').onclick=()=>{let n=advanceEco6(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEco6').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.eco6Passed.includes(t.id))w.eco6Passed.push(t.id);p.widgetDone=ts.every(t=>w.eco6Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All four settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextEco6').onclick=()=>{if(!w.eco6Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.eco6Task=ts[(i+1)%ts.length].id;save();remount();};}
